import { z } from 'zod';

// Fruit Rules page data. Both files in src/content/fruit-rules/ come unchanged from the
// RizzOtto's Arena mod repo (tww3-modding: docs/fruit_rules/). fruit_rules_limits.json is
// generated by the mod build — never edit it by hand; to update, copy both files over the old
// ones. fruit-rules.test.ts parses the committed JSON, so a changed shape fails CI, not the page.

const limitSchema = z.object({
  id: z.number(),
  // own | grp | same | cat | mount | ban — kept open so a new kind degrades to a shared limit.
  kind: z.string(),
  cap: z.number(),
  name: z.string(),
});

const unitSchema = z.object({
  key: z.string(),
  name: z.string(),
  character: z.boolean(),
  mount: z.string().nullish(),
  limits: z.array(z.number()),
  fruit_cap: z.number().nullable(),
  official_cap: z.number().nullable(),
  effective_cap: z.number().nullable(),
  official_stricter: z.boolean(),
  basis: z.string(),
  innate: z
    .object({ drains: z.string().nullish(), nets_or_rampages: z.string().nullish() })
    .nullish(),
});

const abilitySchema = z.object({ name: z.string(), targetable: z.boolean() });

export const fruitRulesSchema = z.object({
  categories: z.array(z.object({ id: z.string(), cap: z.number(), name: z.string() })),
  factions: z.array(
    z.object({
      subculture: z.string(),
      name: z.string(),
      limits: z.array(limitSchema),
      units: z.array(unitSchema),
    }),
  ),
  abilities: z.object({
    drains: z.array(abilitySchema),
    nets: z.array(abilitySchema),
    rampages: z.array(abilitySchema),
  }),
});

export type FruitRulesData = z.infer<typeof fruitRulesSchema>;

export const KNOWN_LIMIT_KINDS = ['own', 'grp', 'same', 'cat', 'mount', 'ban'] as const;

const CATEGORY_TAGS: Record<string, string> = {
  se: 'SE',
  rse: 'RSE',
  '360': '360°',
  chariots: 'Chariot',
  ranged_cav: 'Ranged cav',
  ranged: 'Ranged',
  flying_ranged: 'Flying ranged',
  breath: 'Breath',
};

// Platform faction sigils (public/icons/factions/<id>.png), keyed by the game's subculture.
// Explicit allow-list: an unknown subculture gets no icon instead of a guessed asset URL.
const FACTION_IDS: Record<string, string> = {
  wh_dlc03_sc_bst_beastmen: 'beastmen',
  wh_main_sc_brt_bretonnia: 'bretonnia',
  wh3_dlc23_sc_chd_chaos_dwarfs: 'chaos_dwarfs',
  wh3_main_sc_dae_daemons: 'daemons_of_chaos',
  wh2_main_sc_def_dark_elves: 'dark_elves',
  wh_main_sc_dwf_dwarfs: 'dwarfs',
  wh3_main_sc_cth_cathay: 'grand_cathay',
  wh_main_sc_grn_greenskins: 'greenskins',
  wh2_main_sc_hef_high_elves: 'high_elves',
  wh3_main_sc_kho_khorne: 'khorne',
  wh3_main_sc_ksl_kislev: 'kislev',
  wh2_main_sc_lzd_lizardmen: 'lizardmen',
  wh_dlc08_sc_nor_norsca: 'norsca',
  wh3_main_sc_nur_nurgle: 'nurgle',
  wh3_main_sc_ogr_ogre_kingdoms: 'ogre_kingdoms',
  wh2_main_sc_skv_skaven: 'skaven',
  wh3_main_sc_sla_slaanesh: 'slaanesh',
  wh_main_sc_emp_empire: 'empire',
  wh2_dlc09_sc_tmb_tomb_kings: 'tomb_kings',
  wh3_main_sc_tze_tzeentch: 'tzeentch',
  wh2_dlc11_sc_cst_vampire_coast: 'vampire_coast',
  wh_main_sc_vmp_vampire_counts: 'vampire_counts',
  wh_main_sc_chs_chaos: 'warriors_of_chaos',
  wh_dlc05_sc_wef_wood_elves: 'wood_elves',
};

export type AbilityKind = 'drain' | 'net' | 'rampage' | 'net/rampage';

export interface FruitAbility {
  name: string;
  kind: AbilityKind;
  targetable: boolean;
}

export interface FruitCategory {
  /** Short tag: SE, RSE, 360°, Chariot, … */
  tag: string;
  /** Full name and army limit, e.g. "Single entities (max 4 per army)". */
  title: string;
}

export interface FruitRow {
  key: string;
  name: string;
  /** Characters: the mount, null for the base version. */
  mount: string | null;
  /** The mount's name is an unresolved game text key in the data. */
  mountUnnamed: boolean;
  /** What the army may have: Fruit number or the game's cap where stricter. null = no own limit. */
  limit: number | null;
  /** The game's cap is lower than the Fruit number (shown as a marked limit). */
  gameCapStricter: boolean;
  fruitCap: number | null;
  /** Units: shared limits; characters: the limits they count toward. "Name (cap)". */
  shared: string[];
  categories: FruitCategory[];
  abilities: FruitAbility[];
  basis: string;
  /** Normalized name + mount for the search. */
  searchText: string;
}

export interface FruitFaction {
  /** Anchor id, e.g. "empire" → #faction-empire. */
  id: string;
  name: string;
  iconUrl: string | null;
  units: FruitRow[];
  characters: FruitRow[];
}

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function normalizeSearch(text: string): string {
  return text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/['’`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Search words; a query shorter than 2 characters counts as no search. */
export function searchTokens(query: string): string[] {
  const q = normalizeSearch(query);
  return q.length < 2 ? [] : q.split(' ');
}

export function matchesSearch(row: FruitRow, tokens: string[]): boolean {
  return tokens.every((t) => row.searchText.includes(t));
}

function splitList(value: string | null | undefined): string[] {
  return (value ?? '')
    .split(/,\s*/)
    .map((s) => s.trim())
    .filter(Boolean);
}

export function buildFactions(data: FruitRulesData): FruitFaction[] {
  const categoryByName = new Map(
    data.categories.map((c): [string, FruitCategory] => [
      c.name,
      { tag: CATEGORY_TAGS[c.id] ?? c.name, title: `${c.name} (max ${c.cap} per army)` },
    ]),
  );
  const nets = new Map(data.abilities.nets.map((a) => [a.name, a.targetable]));
  const rampages = new Map(data.abilities.rampages.map((a) => [a.name, a.targetable]));

  return data.factions.map((faction) => {
    const limitsById = new Map(faction.limits.map((l) => [l.id, l]));
    const seen = new Set<string>();
    const units: FruitRow[] = [];
    const characters: FruitRow[] = [];

    for (const unit of faction.units) {
      const name = unit.name.trim();
      const rawMount = unit.mount?.trim() || null;
      const mountUnnamed = rawMount !== null && rawMount.includes('{{');
      const mount = mountUnnamed ? null : rawMount;

      const shared: string[] = [];
      const categories: FruitCategory[] = [];
      for (const id of unit.limits) {
        const limit = limitsById.get(id);
        if (!limit) continue;
        const label = `${limit.name} (${limit.cap})`;
        if (limit.kind === 'cat') {
          categories.push(
            categoryByName.get(limit.name) ?? {
              tag: limit.name,
              title: `${limit.name} (max ${limit.cap} per army)`,
            },
          );
        } else if (limit.kind === 'ban') {
          // A ban shows as "Banned" in the limit column.
        } else if (limit.kind === 'own') {
          if (limit.name === name) continue; // its own limit = the limit column
          shared.push(unit.character ? label : `Counts toward ${label}`);
        } else {
          shared.push(label);
        }
      }

      const abilities: FruitAbility[] = [
        ...splitList(unit.innate?.drains).map(
          (n): FruitAbility => ({ name: n, kind: 'drain', targetable: false }),
        ),
        ...splitList(unit.innate?.nets_or_rampages).map((n): FruitAbility => {
          if (nets.has(n)) return { name: n, kind: 'net', targetable: nets.get(n) === true };
          if (rampages.has(n)) {
            return { name: n, kind: 'rampage', targetable: rampages.get(n) === true };
          }
          return { name: n, kind: 'net/rampage', targetable: false };
        }),
      ];

      const row: FruitRow = {
        key: unit.key,
        name,
        mount,
        mountUnnamed,
        limit: unit.effective_cap,
        gameCapStricter: unit.official_stricter,
        fruitCap: unit.fruit_cap,
        shared,
        categories,
        abilities,
        basis: unit.basis,
        searchText: normalizeSearch(`${name} ${mount ?? ''}`),
      };

      // Variants that differ only in data the page doesn't show (e.g. two Glade Lord
      // weapon sets) would read as duplicate rows — keep the first.
      const signature = JSON.stringify([unit.character, { ...row, key: '' }]);
      if (seen.has(signature)) continue;
      seen.add(signature);

      (unit.character ? characters : units).push(row);
    }

    const factionId = FACTION_IDS[faction.subculture];
    return {
      id: factionId ?? slugify(faction.name),
      name: faction.name,
      iconUrl: factionId ? `/icons/factions/${factionId}.png` : null,
      units,
      characters,
    };
  });
}

export function parseFruitRules(json: unknown): FruitFaction[] {
  return buildFactions(fruitRulesSchema.parse(json));
}

export interface FactionView {
  faction: FruitFaction;
  units: FruitRow[];
  characters: FruitRow[];
  /** Matching rows while searching, 0 otherwise. */
  matches: number;
}

/** No search: every faction with all rows. Search: only factions with matching rows. */
export function filterFactions(factions: FruitFaction[], tokens: string[]): FactionView[] {
  if (tokens.length === 0) {
    return factions.map((f) => ({
      faction: f,
      units: f.units,
      characters: f.characters,
      matches: 0,
    }));
  }
  return factions.flatMap((f) => {
    const units = f.units.filter((r) => matchesSearch(r, tokens));
    const characters = f.characters.filter((r) => matchesSearch(r, tokens));
    const matches = units.length + characters.length;
    return matches > 0 ? [{ faction: f, units, characters, matches }] : [];
  });
}

export interface DocHeading {
  id: string;
  text: string;
}

export interface FruitRulesDoc {
  /** Title and introduction, before the first section. */
  intro: string;
  /** Sections up to and including the one that introduces the faction tables. */
  body: string;
  /** Sections after the faction tables section (none today). */
  after: string;
  toc: DocHeading[];
}

/**
 * Splits the page text so the faction tables render right after the section that introduces
 * them (matched by "Faction tables" in its heading; without one they go at the end).
 */
export function splitFruitRulesDoc(markdown: string): FruitRulesDoc {
  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const h2 = lines.flatMap((line, i) => (/^##\s/.test(line) ? [i] : []));
  const toc = h2.map((i) => {
    const text = lines[i]!.replace(/^##\s+/, '').trim();
    return { id: slugify(text), text };
  });
  const first = h2[0] ?? lines.length;
  const tablesAt = h2.findIndex((i) => /faction tables/i.test(lines[i]!));
  const bodyEnd = tablesAt === -1 ? lines.length : (h2[tablesAt + 1] ?? lines.length);
  return {
    intro: lines.slice(0, first).join('\n'),
    body: lines.slice(first, bodyEnd).join('\n'),
    after: lines.slice(bodyEnd).join('\n'),
    toc,
  };
}
